def backward(weights, penalty, caps, offset, J, extra=None, nfirst=0, need_at=None):
    """Maximum over cumulative counts within the caps. extra[j] is added for every slot of long bin j whose ordinal
    (the short pair, if any, is ordinal 1) is at most nfirst; need_at: the cumulative count after that bin, plus the
    short pair, must be at least nfirst."""
